{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务的项目工时总和Top2",
      "business_question": "按项目汇总已完成任务的工时总和，并降序取前两名。约束：只看已完成任务；指标为工时总和；分析限制为按项目汇总、降序、Top 2。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心问题“已完成任务的项目工时总和排名”，直接支持决策目标（识别工时投入最高的两个已完成项目）。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "total_hours",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
